/** Preview build: voicemail, call handling and call history ship in 0.3.0. */
import { useSwitchboard } from '../data/SwitchboardData';
import { useKit } from '../ui/kit';

export type UserPanelTab = 'voicemail' | 'handling' | 'history';

export function UserPanel({ user, onClose }: { user: string | null; tab: UserPanelTab; onClose: () => void }) {
  const { SidePanel, Alert, Button, Stack, Icon } = useKit();
  const { contactsByUser } = useSwitchboard();
  const c = user ? contactsByUser.get(user) : undefined;
  return (
    <SidePanel
      open={user !== null}
      onClose={onClose}
      width="md"
      icon={<Icon name="lucide:user" size={20} />}
      title={c ? `${c.name} (${c.user})` : user ?? ''}
      footer={
        <Stack direction="row" justifyContent="flex-end" sx={{ width: '100%' }}>
          <Button variant="contained" onClick={onClose}>
            Done
          </Button>
        </Stack>
      }
    >
      <Alert severity="info" title="Arrives in the next build">
        Voicemail, call handling (answer rules) and call history for this user are being finished for version 0.3.0.
      </Alert>
    </SidePanel>
  );
}
