/**
 * Side panels, opened from anywhere, rendered once.
 *
 * The Engage switchboard opens modal dialogs; the Horizon kit's equivalent is
 * the SidePanel drawer. Any view calls `usePanels().open(...)` and the shell's
 * `<PanelHost />` renders whichever panel is open, so views never own panel
 * state and two views cannot open conflicting copies.
 */
import type * as React from 'react';
import { createContext, useCallback, useContext, useMemo, useState } from 'react';

import { UserPanel } from '../panels/UserPanel';
import type { UserPanelTab } from '../panels/UserPanel';
import { QueueStaffingPanel } from '../panels/QueueStaffingPanel';
import { AgentQueuesPanel } from '../panels/AgentQueuesPanel';
import { QueueExpandPanel } from '../panels/QueueExpandPanel';

export type PanelState =
  | { kind: 'user'; user: string; tab: UserPanelTab }
  | { kind: 'staffing'; queue: string }
  | { kind: 'agentQueues'; user: string }
  | { kind: 'queue'; queue: string }
  | null;

interface PanelsApi {
  panel: PanelState;
  openUser: (user: string, tab?: UserPanelTab) => void;
  openStaffing: (queue: string) => void;
  openAgentQueues: (user: string) => void;
  openQueue: (queue: string) => void;
  close: () => void;
}

const Ctx = createContext<PanelsApi | null>(null);

export function PanelsProvider({ children }: { children: React.ReactNode }) {
  const [panel, setPanel] = useState<PanelState>(null);
  const openUser = useCallback((user: string, tab: UserPanelTab = 'voicemail') => setPanel({ kind: 'user', user, tab }), []);
  const openStaffing = useCallback((queue: string) => setPanel({ kind: 'staffing', queue }), []);
  const openAgentQueues = useCallback((user: string) => setPanel({ kind: 'agentQueues', user }), []);
  const openQueue = useCallback((queue: string) => setPanel({ kind: 'queue', queue }), []);
  const close = useCallback(() => setPanel(null), []);
  const value = useMemo(
    () => ({ panel, openUser, openStaffing, openAgentQueues, openQueue, close }),
    [close, openAgentQueues, openQueue, openStaffing, openUser, panel],
  );
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function usePanels(): PanelsApi {
  const v = useContext(Ctx);
  if (!v) throw new Error('usePanels must be used inside PanelsProvider');
  return v;
}

/** Renders the open panel (each panel is a controlled SidePanel). */
export function PanelHost() {
  const { panel, close } = usePanels();
  return (
    <>
      <UserPanel
        user={panel?.kind === 'user' ? panel.user : null}
        tab={panel?.kind === 'user' ? panel.tab : 'voicemail'}
        onClose={close}
      />
      <QueueStaffingPanel queue={panel?.kind === 'staffing' ? panel.queue : null} onClose={close} />
      <AgentQueuesPanel user={panel?.kind === 'agentQueues' ? panel.user : null} onClose={close} />
      <QueueExpandPanel queue={panel?.kind === 'queue' ? panel.queue : null} onClose={close} />
    </>
  );
}
