/** A single portal configuration value, or null. */
export async function readConfig(api: Api, key: string, d: string): Promise<string | null> {
  const rows = asArray<NsRecord>(await api.get(`/configurations/${e(key)}`, { domain: d }));
  const v = rows[0]?.['config-value'] ?? rows[0]?.value;
  return typeof v === 'string' && v.trim() ? v.trim() : null;
}

/** The custom status options (PORTAL_CALL_QUEUE_STATUS_CUSTOM_*). */
export async function readCustomStatuses(api: Api, d: string): Promise<string[]> {
  const rows = asArray<NsRecord>(await api.get(`/configurations/PORTAL_CALL_QUEUE_STATUS_CUSTOM_*`, { domain: d }));
  return rows
    .map((r) => r['config-value'] ?? r.value)
    .filter((v): v is string => typeof v === 'string' && v.trim() !== '')
    .map((v) => v.trim());
}

