export type VoicemailFolder = 'new' | 'save' | 'trash';

export async function readVoicemailCount(api: Api, d: string, u: string): Promise<number> {
  const r = await api.get<Record<string, unknown> | number>(`/domains/${e(d)}/users/${e(u)}/voicemails/new/count`);
  if (typeof r === 'number') return r;
  const n = Number(r?.count ?? r?.unread ?? r?.total ?? 0);
  return Number.isFinite(n) ? n : 0;
}

export async function readVoicemails(
  api: Api,
  d: string,
  u: string,
  folder: VoicemailFolder,
  start: number,
  limit: number,
): Promise<NsVoicemail[]> {
  return asArray<NsVoicemail>(
    await api.get(`/domains/${e(d)}/users/${e(u)}/voicemails/${e(folder)}`, { start, limit }),
  );
}

export async function deleteVoicemail(api: Api, d: string, u: string, folder: VoicemailFolder, id: string): Promise<void> {
  await api.delete(`/domains/${e(d)}/users/${e(u)}/voicemails/${e(folder)}/${e(id)}`);
}

