// ---------------------------------------------------------------------------
// History, recordings, statistics
// ---------------------------------------------------------------------------

/** "2026-09-24T04:00:00Z" - the CDR window form. */
export function isoZ(ms: number): string {
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, 'Z');
}

/** "2026-09-24T04:00:00Z[UTC]" - the statistics window form. */
function zoned(ms: number, tz = 'UTC'): string {
  return `${isoZ(ms)}[${tz}]`;
}

export async function readCdrs(
  api: Api,
  d: string,
  opts: { startMs: number; endMs: number; user?: string; limit?: number; offset?: number },
): Promise<NsCdr[]> {
  const params: Record<string, unknown> = {
    'datetime-start': isoZ(opts.startMs),
    'datetime-end': isoZ(opts.endMs),
    limit: opts.limit ?? 100,
    start: opts.offset ?? 0,
  };
  const r = opts.user
    ? await api.get(`/domains/${e(d)}/users/${e(opts.user)}/cdrs`, params)
    : await api.get(`/domains/${e(d)}/cdrs`, params);
  return asArray<NsCdr>(r);
}

/** Recording metadata for one CDR (the switch returns a signed URL when one exists). */
export async function readCdrRecording(api: Api, d: string, cdrId: string): Promise<NsRecord[]> {
  const r = await api.get(`/domains/${e(d)}/cdrs/${e(cdrId)}/recording`);
  return Array.isArray(r) ? (r as NsRecord[]) : r && typeof r === 'object' ? [r as NsRecord] : [];
}

type StatsWindow = { startMs: number; endMs: number };

function statsParams(w: StatsWindow): Record<string, unknown> {
  return { 'datetime-start': zoned(w.startMs), 'datetime-end': zoned(w.endMs) };
}

/** Object keyed by queue extension. */
export async function readQueueStats(api: Api, d: string, w: StatsWindow): Promise<Record<string, NsRecord>> {
  const r = await api.get(`/domains/${e(d)}/statistics/callqueues/per-queue`, statsParams(w));
  return r && typeof r === 'object' && !Array.isArray(r) ? (r as Record<string, NsRecord>) : {};
}

export async function readQueueStatsAggregate(api: Api, d: string, w: StatsWindow): Promise<NsRecord> {
  const r = await api.get(`/domains/${e(d)}/statistics/callqueues/aggregate`, statsParams(w));
  return r && typeof r === 'object' && !Array.isArray(r) ? (r as NsRecord) : {};
}

/** Object keyed by agent extension. */
export async function readAgentStats(api: Api, d: string, w: StatsWindow): Promise<Record<string, NsRecord>> {
  const r = await api.get(`/domains/${e(d)}/statistics/agent`, statsParams(w));
  return r && typeof r === 'object' && !Array.isArray(r) ? (r as Record<string, NsRecord>) : {};
}

export async function readAbandoned(api: Api, d: string, w: StatsWindow): Promise<NsRecord[]> {
  return asArray<NsRecord>(await api.get(`/domains/${e(d)}/callqueuereport/abandoned`, statsParams(w)));
}

/** Object keyed by dialed number. */
export async function readDnisStats(api: Api, d: string, w: StatsWindow): Promise<Record<string, NsRecord>> {
  const r = await api.get(`/domains/${e(d)}/statistics/dnis`, statsParams(w));
  return r && typeof r === 'object' && !Array.isArray(r) ? (r as Record<string, NsRecord>) : {};
}

