export const PATCH_REASON =
  'NetSapiens only offers this as a PATCH request, and Horizon apps may use GET, POST, PUT and DELETE. It works once NetSapiens allows PATCH (or adds a POST/PUT form) for apps.';

export const BLOCKED = {
  answer: 'Answer from your phone or softphone. ' + PATCH_REASON,
  hold: 'Hold from your phone or softphone. ' + PATCH_REASON,
  transfer: 'Transfer from your phone or softphone. ' + PATCH_REASON,
  pickup: 'Queue pickup (intercept) is a transfer. ' + PATCH_REASON,
  voicemailSave: 'Moving a voicemail between folders is a PATCH request. ' + PATCH_REASON,
} as const;
