/**
 * The operator rail shared by Real-Time and Operate:
 *   My Calls    the operator's own live calls (ActiveCallCard)
 *   Call Parks  park slots and parked calls, Dynamic Call Parking switch,
 *               per-site scope when parks are split by site
 *   Dial Pad    click-to-call from the operator's phone (collapsible)
 */
import type * as React from 'react';
import { useMemo, useState } from 'react';

import type { ParkedCall, ParkSlot } from '../../types';
import { useSwitchboard } from '../../data/SwitchboardData';
import { useActions } from '../../data/actions';
import { usePanels } from '../../data/panels';
import { isBoolean, oneOf, usePersistentState } from '../../data/persist';
import * as ns from '../../api/ns';
import { linesFor } from '../../model/calls';
import { ALL, detectParkTopology, visibleParks } from '../../model/directory';
import { formatPhone } from '../../model/format';
import { useKit } from '../../ui/kit';
import { Empty, Pill, SectionTitle, SmallButton, Timer, tint } from '../../ui/bits';
import { ActiveCallCard } from './ActiveCallCard';

export function OperatorRail() {
  const { Box, Stack, Divider } = useKit();
  return (
    <Stack sx={{ height: '100%', minHeight: 0 }}>
      <Box sx={{ flex: 1, minHeight: 0, overflowY: 'auto', pr: 0.5 }}>
        <MyCalls />
        <Divider sx={{ my: 2 }} />
        <CallParks />
      </Box>
      <DialPad />
    </Stack>
  );
}

// ---------------------------------------------------------------------------
// My Calls
// ---------------------------------------------------------------------------

function MyCalls() {
  const { Stack, Typography } = useKit();
  const { operator, domain, calls, caps } = useSwitchboard();
  const { openUser } = usePanels();
  const [dynamicPark] = usePersistentState<boolean>('rail.dynamicPark', false, isBoolean);
  const here = !!operator.ext && operator.domain === domain;
  const lines = useMemo(() => (here ? linesFor(calls, operator.ext) : []), [calls, here, operator.ext]);

  return (
    <section aria-label="My calls">
      <SectionTitle
        icon="lucide:phone"
        title="My Calls"
        count={lines.length}
        right={
          here ? (
            <Stack direction="row" spacing={0.5}>
              <SmallButton variant="text" icon="lucide:voicemail" label="Voicemail" onClick={() => openUser(operator.ext, 'voicemail')} />
              <SmallButton variant="text" icon="lucide:history" label="History" onClick={() => openUser(operator.ext, 'history')} />
            </Stack>
          ) : undefined
        }
      />
      {!operator.ext ? (
        <Empty>Your sign-in has no extension, so there are no calls of your own to show or control here.</Empty>
      ) : !here ? (
        <Empty>
          Your extension is in {operator.domain}. Your calls show here when you are viewing that domain.
        </Empty>
      ) : lines.length === 0 ? (
        <Empty>No active calls</Empty>
      ) : (
        <Stack spacing={1}>
          {lines.map((l) => (
            <ActiveCallCard key={l.call.key} line={l} dynamicPark={dynamicPark} />
          ))}
        </Stack>
      )}
      {here && !caps.domainCalls ? (
        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
          Showing your own calls only.
        </Typography>
      ) : null}
    </section>
  );
}

// ---------------------------------------------------------------------------
// Call Parks
// ---------------------------------------------------------------------------

function CallParks() {
  const { Stack, Typography, Switch, Box, ToggleButtonGroup } = useKit();
  const { parks } = useSwitchboard();
  const [dynamicPark, setDynamicPark] = usePersistentState<boolean>('rail.dynamicPark', false, isBoolean);
  const [scope, setScope] = usePersistentState<'site' | 'all'>('rail.parkScope', 'site', oneOf('site', 'all'));
  const [site] = usePersistentState<string>('rt.site', ALL);

  const topology = detectParkTopology(parks);
  const effectiveScope = topology === 'domain' ? 'all' : scope;
  const shown = visibleParks(parks, topology, effectiveScope, site);
  const parkedTotal = parks.reduce((n, p) => n + Math.max(p.calls.length, p.reportedCount), 0);
  const showScope = topology === 'per-site' && site && site !== ALL;

  return (
    <section aria-label="Call parks">
      <SectionTitle icon="lucide:circle-parking" title="Call Parks" count={parkedTotal} />
      <Box sx={{ mb: 1.5, px: 1, py: 0.75, borderRadius: 1, border: 1, borderColor: 'divider', bgcolor: 'action.hover' }}>
        <Stack direction="row" alignItems="center" justifyContent="space-between">
          <Typography variant="caption" sx={{ fontWeight: 600 }}>
            Dynamic Call Parking
          </Typography>
          <Stack direction="row" alignItems="center" spacing={0.5}>
            <Switch
              checked={dynamicPark}
              onChange={(_e: React.ChangeEvent<HTMLInputElement>, checked: boolean) => setDynamicPark(checked)}
              size="small"
              inputProps={{ 'aria-label': 'Dynamic Call Parking' }}
              slotProps={{ input: { 'aria-label': 'Dynamic Call Parking' } }}
            />
            <Typography sx={{ fontSize: 10, fontWeight: 700, color: 'text.secondary', width: 26, textAlign: 'right' }}>
              {dynamicPark ? 'ON' : 'OFF'}
            </Typography>
          </Stack>
        </Stack>
        <Typography variant="caption" color="text.secondary">
          {dynamicPark ? 'Park sends the call to the next free slot.' : 'Park asks you which slot to use.'}
        </Typography>
      </Box>

      {showScope ? (
        <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }} role="group" aria-label="Park slot scope">
          <Typography variant="caption" sx={{ fontWeight: 600 }}>
            Parks
          </Typography>
          <ToggleButtonGroup
            size="small"
            exclusive
            value={scope}
            onChange={(_e: unknown, v: unknown) => {
              if (v === 'site' || v === 'all') setScope(v);
            }}
            options={[
              { value: 'site', label: 'This site' },
              { value: 'all', label: 'All' },
            ]}
          />
        </Stack>
      ) : null}

      {parks.length === 0 ? (
        <Empty>No park slots</Empty>
      ) : shown.length === 0 ? (
        <Empty action={<SmallButton variant="text" label="Show all parks" onClick={() => setScope('all')} />}>
          No park slots at {site}.
        </Empty>
      ) : dynamicPark ? (
        <DynamicParkList parks={shown} />
      ) : (
        <Stack spacing={1}>
          {shown.map((p) => (
            <ParkSlotCard key={p.ext} slot={p} />
          ))}
        </Stack>
      )}
    </section>
  );
}

function slotLabel(p: ParkSlot): string {
  return p.name && p.name !== p.ext ? `${p.name} (${p.ext})` : p.ext;
}

function DynamicParkList({ parks }: { parks: ParkSlot[] }) {
  const { Stack } = useKit();
  const calls = parks.flatMap((p) => p.calls);
  if (!calls.length) return <Empty>No parked calls. Park sends the next one to the first free slot.</Empty>;
  return (
    <Stack spacing={1}>
      {calls.map((c) => (
        <ParkedCallCard key={c.key} call={c} />
      ))}
    </Stack>
  );
}

function ParkSlotCard({ slot }: { slot: ParkSlot }) {
  const { Box, Stack, Typography, Icon } = useKit();
  const count = Math.max(slot.calls.length, slot.reportedCount);
  const occupied = count > 0;
  const label = slotLabel(slot);
  const title = occupied
    ? `${label} - ${count} call${count === 1 ? '' : 's'} parked. Dial ${slot.ext} to retrieve.`
    : `${label} - Empty. Transfer a call here to park it.`;
  return (
    <Box
      title={title}
      sx={{
        p: 1,
        borderRadius: 1.5,
        border: 1,
        borderColor: occupied ? tint('info', 0.4) : 'divider',
        bgcolor: occupied ? tint('info', 0.1) : 'action.hover',
      }}
    >
      <Stack direction="row" spacing={1} alignItems="center">
        <Box sx={{ color: occupied ? 'info.main' : 'text.disabled', display: 'flex' }}>
          <Icon name="lucide:circle-parking" size={16} />
        </Box>
        <Typography variant="body2" sx={{ fontWeight: 600, flex: 1, minWidth: 0 }} noWrap>
          {slot.name && slot.name !== slot.ext ? slot.name : 'Park'}{' '}
          <Box component="span" sx={{ color: 'primary.main', fontVariantNumeric: 'tabular-nums' }}>
            {slot.ext}
          </Box>
        </Typography>
        {occupied ? <Pill tone="info" label={count} /> : (
          <Typography variant="caption" color="text.secondary">
            Empty
          </Typography>
        )}
      </Stack>
      {slot.calls.length ? (
        <Stack spacing={0.75} sx={{ mt: 1 }}>
          {slot.calls.map((c) => (
            <ParkedCallCard key={c.key} call={c} />
          ))}
        </Stack>
      ) : null}
    </Box>
  );
}

function ParkedCallCard({ call }: { call: ParkedCall }) {
  const { Paper, Stack, Typography, Box } = useKit();
  const sb = useSwitchboard();
  const { run, isPending } = useActions();
  const { contactsByUser, operator, domain, api } = sb;
  const here = !!operator.ext && operator.domain === domain;
  const name = call.callerName || call.callerNumber || 'Parked caller';
  const byName = call.parkedBy ? contactsByUser.get(call.parkedBy)?.name : '';
  const retrieve = () =>
    run(`unpark:${call.key}`, () => ns.unpark(api, domain, operator.ext, call.slot), {
      success: 'Retrieving parked call. Your phone will ring.',
      failure: 'Unable to retrieve the parked call.',
    }).then(() => sb.refresh(['calls', 'queued', 'parks']));
  return (
    <Paper variant="outlined" sx={{ p: 1 }}>
      <Stack direction="row" spacing={1} alignItems="center">
        <Typography variant="caption" sx={{ fontWeight: 700 }}>
          Parked Call
        </Typography>
        <Pill tone="info" label={call.slot} />
        <Box sx={{ flex: 1 }} />
        <Timer since={call.startedAt} />
      </Stack>
      <Typography variant="body2" sx={{ fontWeight: 600, mt: 0.5 }} noWrap title={name}>
        {name}
      </Typography>
      {call.callerName && call.callerNumber && call.callerName !== call.callerNumber ? (
        <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
          {formatPhone(call.callerNumber)}
        </Typography>
      ) : null}
      {call.parkedBy ? (
        <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
          Parked by {byName ? `${byName} (${call.parkedBy})` : call.parkedBy}
        </Typography>
      ) : null}
      <Stack direction="row" spacing={1} sx={{ mt: 0.75 }}>
        <SmallButton
          icon="lucide:phone"
          label="Retrieve"
          disabled={!here}
          busy={isPending(`unpark:${call.key}`)}
          title={here ? 'Retrieve this parked call. Your phone will ring.' : 'Retrieve works from your own extension in its own domain.'}
          onClick={() => void retrieve()}
        />
      </Stack>
    </Paper>
  );
}

// ---------------------------------------------------------------------------
// Dial Pad
// ---------------------------------------------------------------------------

const KEYS: Array<[string, string]> = [
  ['1', ''],
  ['2', 'ABC'],
  ['3', 'DEF'],
  ['4', 'GHI'],
  ['5', 'JKL'],
  ['6', 'MNO'],
  ['7', 'PQRS'],
  ['8', 'TUV'],
  ['9', 'WXYZ'],
  ['*', ''],
  ['0', '+'],
  ['#', ''],
];

function DialPad() {
  const { Box, Stack, Typography, Button, TextField, IconButton, Icon } = useKit();
  const sb = useSwitchboard();
  const { run, isPending } = useActions();
  const { operator, api } = sb;
  const [open, setOpen] = usePersistentState<boolean>('rail.dialPadOpen', false, isBoolean);
  const [number, setNumber] = useState('');
  const canDial = !!operator.ext;

  const call = () => {
    const n = number.trim();
    if (!n || !canDial) return;
    void run('dial', () => ns.originate(api, operator.domain, operator.ext, n), {
      success: `Calling ${n}`,
      failure: 'Failed to place call.',
    }).then(() => sb.refresh(['calls']));
  };

  return (
    <Box sx={{ flexShrink: 0, borderTop: 1, borderColor: 'divider', mt: 1, pt: 0.5 }}>
      <Button
        fullWidth
        color="inherit"
        onClick={() => setOpen(!open)}
        aria-expanded={open}
        startIcon={<Icon name="lucide:phone" size={16} />}
        endIcon={<Icon name={open ? 'lucide:chevron-down' : 'lucide:chevron-up'} size={16} />}
        sx={{ justifyContent: 'flex-start', textTransform: 'none', fontWeight: 700, '& .MuiButton-endIcon': { ml: 'auto' } }}
      >
        Dial Pad
      </Button>
      {open ? (
        <Stack spacing={1} sx={{ pb: 1 }}>
          {!canDial ? (
            <Typography variant="caption" color="text.secondary">
              Your sign-in has no extension to call from.
            </Typography>
          ) : null}
          <Stack direction="row" spacing={0.5} alignItems="center">
            <TextField
              size="small"
              fullWidth
              autoFocus
              placeholder="Enter number"
              value={number}
              disabled={!canDial}
              onChange={(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setNumber(e.target.value.replace(/[^0-9*#]/g, ''))}
              onKeyDown={(e: React.KeyboardEvent) => {
                if (e.key === 'Enter') call();
              }}
              inputProps={{ 'aria-label': 'Phone number', inputMode: 'tel', style: { textAlign: 'center', fontFamily: 'monospace', fontSize: 18 } }}
            />
            {number ? (
              <IconButton icon="lucide:delete" aria-label="Delete last digit" size="small" onClick={() => setNumber(number.slice(0, -1))} />
            ) : null}
          </Stack>
          <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 0.75 }}>
            {KEYS.map(([k, sub]) => (
              <Button
                key={k}
                variant="outlined"
                color="inherit"
                disabled={!canDial}
                aria-label={`Dial ${k}`}
                onClick={() => setNumber((n) => n + k)}
                sx={{ height: 52, flexDirection: 'column', lineHeight: 1, borderColor: 'divider' }}
              >
                <Box component="span" sx={{ fontSize: 18, fontWeight: 700 }}>
                  {k}
                </Box>
                <Box component="span" sx={{ fontSize: 9, letterSpacing: 1, color: 'text.secondary', minHeight: 11 }}>
                  {sub}
                </Box>
              </Button>
            ))}
          </Box>
          <Stack direction="row" spacing={1}>
            <SmallButton label="Clear" color="inherit" disabled={!number} onClick={() => setNumber('')} />
            <Box sx={{ flex: 1 }}>
              <SmallButton
                fullWidth
                variant="contained"
                color="success"
                icon="lucide:phone"
                label="Call"
                title="Dial this number and your phone will ring"
                disabled={!number.trim() || !canDial}
                busy={isPending('dial')}
                onClick={call}
              />
            </Box>
          </Stack>
        </Stack>
      ) : null}
    </Box>
  );
}
