/**
 * Call normalisation: one `CallLeg` per active call, read from either the v2
 * `call-*` vocabulary (GET /domains/:d/calls) or the older hyphen/snake forms
 * (queued-call rows, older switches). From legs we derive:
 *   - `lineFor`       one extension's view of a call (contact cards, My Calls)
 *   - `queueCallers`  waiting + answered callers per queue
 *   - `parkedCalls`   calls sitting in a park orbit
 *
 * Live v2 shape captured on the lab (a queue call answered by an agent):
 *   call-orig-call-id, call-orig-user, call-orig-name, caller-id-number,
 *   call-dialed-number, call-through-action "QueueDispatch",
 *   call-through-user "<queue ext>", call-through-name, call-term-user "<agent>",
 *   call-term-uri, call-start-datetime, call-answer-datetime,
 *   call-orig-info "active", call-term-info "active", call-session-id
 */
import type { CallLeg, Line, LineStatus, NsRecord, ParkedCall, QueueCaller } from '../types';
import {
  baseExtension,
  cleanNumber,
  digitsOf,
  first,
  lower,
  parseSwitchTime,
  pick,
  toIntOrUndef,
  userPart,
} from './raw';
import { formatPhone } from './format';

export function normaliseCall(raw: NsRecord, index = 0): CallLeg | null {
  const origId = pick(raw, 'call-orig-call-id', 'orig-callid', 'orig_callid', 'call-id', 'callid');
  const termId = pick(raw, 'call-term-call-id', 'term-callid', 'term_callid');
  const throughId = pick(raw, 'call-through-call-id', 'through-callid', 'through_callid');
  const sessionId = pick(raw, 'call-session-id', 'session-id', 'sessionId', 'session_id');
  const controlIds = Array.from(new Set([origId, termId, throughId].filter(Boolean)));

  const origUser = userPart(pick(raw, 'call-orig-user', 'orig-user', 'orig_user', 'user'));
  const termUser = userPart(pick(raw, 'call-term-user', 'term-user', 'term_user', 'term_sub'));
  const throughUser = userPart(pick(raw, 'call-through-user', 'through-user', 'through_user'));

  if (!controlIds.length && !sessionId && !origUser && !termUser) return null;

  const origNumber = cleanNumber(
    pick(
      raw,
      'caller-id-number',
      'call-orig-caller-id-number',
      'orig-from-user',
      'orig_from_user',
      'call-orig-from-user',
      'ani',
      'call-orig-uri',
      'orig-from-uri',
      'orig_from_uri',
    ),
  );

  return {
    key: sessionId || origId || termId || `call-${index}`,
    controlIds,
    sessionId,
    origUser,
    origName: pick(raw, 'call-orig-name', 'caller-id-name', 'orig-from-name', 'orig_from_name', 'orig-name', 'orig_name', 'orig-sub-name'),
    origNumber,
    termUser,
    termName: pick(raw, 'call-term-name', 'term-to-name', 'term_to_name', 'term-name', 'orig-to-name'),
    throughUser,
    throughName: pick(raw, 'call-through-name', 'through-name', 'through_name'),
    throughAction: pick(raw, 'call-through-action', 'through-action', 'through_action', 'by_action'),
    dialed: cleanNumber(pick(raw, 'call-dialed-number', 'dnis', 'orig-to-user', 'orig_to_user', 'call-orig-to-user')),
    termUri: pick(raw, 'call-term-uri', 'term-uri', 'term_uri'),
    origInfo: lower(pick(raw, 'call-orig-info', 'orig-call-info', 'orig_call_info', 'call-state', 'call_state')),
    termInfo: lower(pick(raw, 'call-term-info', 'term-call-info', 'term_call_info')),
    startedAt: parseSwitchTime(pick(raw, 'call-start-datetime', 'time-start', 'time_start', 'time-begin', 'time_begin')),
    answeredAt: parseSwitchTime(pick(raw, 'call-answer-datetime', 'time-answer', 'time_answer')),
    raw,
  };
}

export function normaliseCalls(rows: unknown): CallLeg[] {
  if (!Array.isArray(rows)) return [];
  const out: CallLeg[] = [];
  const seen = new Set<string>();
  rows.forEach((r, i) => {
    if (!r || typeof r !== 'object') return;
    const leg = normaliseCall(r as NsRecord, i);
    if (!leg || seen.has(leg.key)) return;
    seen.add(leg.key);
    out.push(leg);
  });
  return out;
}

function sameExt(a: string, b: string): boolean {
  if (!a || !b) return false;
  return a === b || baseExtension(a) === b || a === baseExtension(b);
}

/** Is this extension a party to the call (either leg)? */
export function involves(call: CallLeg, ext: string): 'orig' | 'term' | null {
  if (sameExt(call.origUser, ext)) return 'orig';
  if (sameExt(call.termUser, ext)) return 'term';
  return null;
}

function stateFromInfo(info: string, answered: boolean): LineStatus {
  if (/held|hold/.test(info)) return 'held';
  if (/alert|ring/.test(info)) return 'ringing';
  if (/progress|dial|trying|early/.test(info)) return 'dialing';
  if (/active|connect|accept|talk|answer/.test(info)) return 'active';
  if (!info) return answered ? 'active' : 'unknown';
  return answered ? 'active' : 'unknown';
}

/**
 * One extension's view of a call. `null` when the extension is not a party.
 * Direction is relative to that extension; state comes from that
 * extension's own leg first.
 */
export function lineFor(call: CallLeg, ext: string): Line | null {
  const side = involves(call, ext);
  if (!side) return null;
  const answered = call.answeredAt != null;
  const ownInfo = side === 'orig' ? call.origInfo : call.termInfo;
  const otherInfo = side === 'orig' ? call.termInfo : call.origInfo;
  let status = stateFromInfo(ownInfo, answered);
  if (status === 'unknown') status = stateFromInfo(otherInfo, answered);
  if (status === 'unknown') status = answered ? 'active' : side === 'orig' ? 'dialing' : 'ringing';
  // An unanswered leg is never "active" whatever the info field says.
  if (!answered && status === 'active') status = side === 'orig' ? 'dialing' : 'ringing';

  let peerName = '';
  let peerNumber = '';
  if (side === 'orig') {
    peerNumber = first(
      call.dialed && call.dialed !== ext ? call.dialed : '',
      call.termUser !== ext ? call.termUser : '',
    );
    peerName = first(call.termName, call.throughName, peerNumber);
  } else {
    const origDigits = digitsOf(call.origNumber);
    peerNumber = origDigits.length >= 7 ? call.origNumber : first(call.origNumber, call.origUser);
    peerName = first(call.origName, peerNumber);
  }
  return {
    call,
    direction: side === 'orig' ? 'outbound' : 'inbound',
    status,
    peerName,
    peerNumber,
    startedAt: call.startedAt,
    answeredAt: call.answeredAt,
  };
}

/** Live lines for one extension, primary first: not-held before held, then oldest. */
export function linesFor(calls: CallLeg[], ext: string): Line[] {
  const lines: Line[] = [];
  for (const c of calls) {
    const l = lineFor(c, ext);
    if (l) lines.push(l);
  }
  lines.sort((a, b) => {
    const ah = a.status === 'held' ? 1 : 0;
    const bh = b.status === 'held' ? 1 : 0;
    if (ah !== bh) return ah - bh;
    const at = a.answeredAt ?? a.startedAt ?? Number.MAX_SAFE_INTEGER;
    const bt = b.answeredAt ?? b.startedAt ?? Number.MAX_SAFE_INTEGER;
    return at - bt;
  });
  return lines;
}

/** Names that carry no information and should give way to the number. */
const JUNK_NAME =
  /^(unknown|wireless caller|anonymous|restricted|no caller id|name unavailable|out of area|toll free|private|cell phone|cellular|v-?\d+)$/i;

export function usefulCallerName(name: string, number: string): boolean {
  const n = (name ?? '').trim();
  if (!n || !/[a-z]/i.test(n) || JUNK_NAME.test(n)) return false;
  const nd = digitsOf(n);
  return !(nd && nd === digitsOf(number));
}

function callerLabel(name: string, number: string): { name: string; number: string } {
  const formatted = formatPhone(number);
  return {
    name: usefulCallerName(name, number) ? name : formatted || 'Unknown',
    number: formatted,
  };
}

/** A queue call derived from a domain call leg dispatched through queue `q`. */
function callerFromLeg(call: CallLeg, q: string): QueueCaller {
  const active = call.answeredAt != null && call.termUser !== '' && call.termUser !== q;
  const { name, number } = callerLabel(call.origName, call.origNumber || call.origUser);
  return {
    key: `leg:${call.key}`,
    controlIds: call.controlIds,
    queue: q,
    callerName: name,
    callerNumber: number,
    startedAt: call.startedAt,
    answeredAt: call.answeredAt,
    reportedWaitSeconds: null,
    isActive: active,
    agentUser: active ? call.termUser : '',
    agentName: active ? call.termName : '',
    position: null,
    placeholder: false,
  };
}

/** A queue call from a GET /queuedcall/:q row. */
export function callerFromQueuedRow(row: NsRecord, q: string, index: number): QueueCaller | null {
  const leg = normaliseCall(row, index);
  const id = pick(row, 'call-id', 'call-orig-call-id', 'orig-callid', 'orig_callid', 'callid');
  const number = cleanNumber(
    pick(row, 'caller-id-number', 'call-orig-caller-id-number', 'orig-from-user', 'orig_from_user', 'call-orig-user', 'ani', 'orig_from_uri'),
  );
  const rawName = pick(row, 'caller-id-name', 'call-orig-name', 'orig-from-name', 'orig_from_name', 'orig_name');
  const { name, number: formatted } = callerLabel(rawName, number);
  const started = parseSwitchTime(
    pick(row, 'time-start', 'call-start-datetime', 'queue-time-start', 'time_start', 'time-begin', 'time_begin'),
  );
  const answered = parseSwitchTime(pick(row, 'time-answer', 'call-answer-datetime', 'time_answer'));
  const termUri = pick(row, 'term-uri', 'term_uri', 'call-term-uri');
  const termUser = baseExtension(pick(row, 'term-user', 'term_user', 'call-term-user', 'term_sub'));
  // A leg held in another orbit (e.g. parked) is not this queue's caller.
  if (/call-queue/i.test(termUri) && termUser && termUser !== q) return null;
  const info = lower(pick(row, 'orig-call-info', 'orig_call_info', 'call-orig-info', 'term-call-info', 'term_call_info', 'call-term-info'));
  const isActive = !/call-queue/i.test(termUri) && answered != null && /active/.test(info) && !!termUser && termUser !== q;
  const ids = Array.from(new Set([id, ...(leg?.controlIds ?? [])].filter(Boolean)));
  if (!ids.length && !number) return null;
  return {
    key: `q:${q}:${ids[0] || `${number}-${index}`}`,
    controlIds: ids,
    queue: q,
    callerName: name,
    callerNumber: formatted,
    startedAt: started,
    answeredAt: answered,
    reportedWaitSeconds: toIntOrUndef(row['wait-time-seconds'] ?? row['wait_time']) ?? null,
    isActive,
    agentUser: isActive ? termUser : '',
    agentName: isActive ? pick(row, 'term-name', 'call-term-name', 'term_to_name') : '',
    position: toIntOrUndef(row.position) ?? null,
    placeholder: false,
  };
}

/**
 * Waiting and answered callers for one queue, merged from the queue's own
 * queued-call read and the domain calls feed (a call dispatched through the
 * queue carries the queue extension as `call-through-user`). Deduped by call id.
 */
export function queueCallers(
  q: string,
  queuedRows: NsRecord[] | undefined,
  calls: CallLeg[],
): { waiting: QueueCaller[]; active: QueueCaller[] } {
  const byId = new Map<string, QueueCaller>();
  const add = (c: QueueCaller) => {
    const id = c.controlIds[0] || c.key;
    const prev = byId.get(id);
    if (!prev) {
      byId.set(id, c);
      return;
    }
    // Prefer the richer record: answered beats waiting, known start beats none.
    byId.set(id, {
      ...prev,
      isActive: prev.isActive || c.isActive,
      agentUser: prev.agentUser || c.agentUser,
      agentName: prev.agentName || c.agentName,
      answeredAt: prev.answeredAt ?? c.answeredAt,
      startedAt: prev.startedAt ?? c.startedAt,
      callerName: prev.callerName !== 'Unknown' ? prev.callerName : c.callerName,
      callerNumber: prev.callerNumber || c.callerNumber,
    });
  };
  (queuedRows ?? []).forEach((r, i) => {
    const c = callerFromQueuedRow(r, q, i);
    if (c) add(c);
  });
  for (const call of calls) {
    const viaQueue = call.throughUser === q || (call.termUser === q && /call-queue/i.test(call.termUri));
    if (!viaQueue) continue;
    add(callerFromLeg(call, q));
  }
  const all = Array.from(byId.values());
  const waiting = all
    .filter((c) => !c.isActive)
    .sort((a, b) => (a.startedAt ?? Number.MAX_SAFE_INTEGER) - (b.startedAt ?? Number.MAX_SAFE_INTEGER));
  const active = all
    .filter((c) => c.isActive)
    .sort((a, b) => (a.answeredAt ?? 0) - (b.answeredAt ?? 0));
  return { waiting, active };
}

/** Placeholder rows when the switch reports a count but gave no call detail. */
export function placeholderCallers(q: string, count: number): QueueCaller[] {
  const n = Math.min(Math.max(0, count), 5);
  return Array.from({ length: n }, (_, i) => ({
    key: `ph:${q}:${i}`,
    controlIds: [],
    queue: q,
    callerName: `Caller ${i + 1} waiting in queue`,
    callerNumber: '',
    startedAt: null,
    answeredAt: null,
    reportedWaitSeconds: null,
    isActive: false,
    agentUser: '',
    agentName: '',
    position: i + 1,
    placeholder: true,
  }));
}

/** Seconds a caller has been waiting, from its start or the server's own count. */
export function callerWaitSeconds(c: QueueCaller, now: number): number {
  if (c.startedAt != null) return Math.max(0, Math.floor((now - c.startedAt) / 1000));
  return c.reportedWaitSeconds ?? 0;
}

/**
 * Calls held in a park orbit. A parked call is dispatched through, or
 * terminated on, the orbit's extension and is not connected to a person.
 */
export function parkedCalls(slot: string, queuedRows: NsRecord[] | undefined, calls: CallLeg[]): ParkedCall[] {
  const out = new Map<string, ParkedCall>();
  for (const call of calls) {
    const inSlot = call.throughUser === slot || call.termUser === slot;
    if (!inSlot) continue;
    const { name, number } = callerLabel(call.origName, call.origNumber || call.origUser);
    const id = call.controlIds[0] || call.key;
    out.set(id, {
      key: `park:${slot}:${id}`,
      slot,
      controlIds: call.controlIds,
      callerName: name,
      callerNumber: number,
      startedAt: call.startedAt,
      parkedBy: pick(call.raw, 'by_sub', 'by_user', 'call-by-user'),
    });
  }
  (queuedRows ?? []).forEach((r, i) => {
    const c = callerFromQueuedRow(r, slot, i);
    if (!c) return;
    const id = c.controlIds[0] || c.key;
    if (out.has(id)) return;
    out.set(id, {
      key: `park:${slot}:${id}`,
      slot,
      controlIds: c.controlIds,
      callerName: c.callerName,
      callerNumber: c.callerNumber,
      startedAt: c.startedAt,
      parkedBy: pick(r, 'by_sub', 'by_user'),
    });
  });
  return Array.from(out.values());
}

/** Random 16-char [a-z0-9] call id, the shape the switch expects on originate. */
export function newCallId(): string {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz0123456789';
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  let out = '';
  for (const b of bytes) out += alphabet[b % alphabet.length];
  return out;
}
