/**
 * Directory filters, grouping and sort - the Real-Time toolbar rules
 * (directoryFilters.ts in the Engage switchboard).
 */
import type { Contact, ParkSlot, QueueView } from '../types';

export const ALL = 'all';

const EMPTY_SENTINELS = new Set(['', 'undefined', 'null', 'n/a', '&nbsp;', '-']);

/** Trimmed display value, or "" for the switch's many spellings of "none". */
export function normFilterValue(raw: unknown): string {
  const s = typeof raw === 'string' ? raw.trim() : raw == null ? '' : String(raw).trim();
  return EMPTY_SENTINELS.has(s.toLowerCase()) ? '' : s;
}

export function filterKey(raw: unknown): string {
  return normFilterValue(raw).toLowerCase();
}

/** Empty or "all" matches everything, including rows with no value. */
export function matchesFilter(rowValue: unknown, selected: string): boolean {
  if (!selected || selected === ALL) return true;
  return filterKey(rowValue) === filterKey(selected);
}

function uniqueSorted(values: string[]): string[] {
  const seen = new Map<string, string>();
  for (const v of values) {
    const n = normFilterValue(v);
    if (!n) continue;
    const k = n.toLowerCase();
    if (!seen.has(k)) seen.set(k, n);
  }
  return Array.from(seen.values()).sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
}

export function collectFilterValues(
  contacts: Contact[],
  queues: QueueView[],
  parks: ParkSlot[],
): { sites: string[]; departments: string[] } {
  return {
    sites: uniqueSorted([
      ...contacts.map((c) => c.site),
      ...queues.map((q) => q.site),
      ...parks.map((p) => p.site),
    ]),
    departments: uniqueSorted([...contacts.map((c) => c.department), ...queues.map((q) => q.department)]),
  };
}

/** A stored selection that no longer exists falls back to "all". */
export function reconcileSelection(stored: string, available: string[]): string {
  if (!stored || stored === ALL) return ALL;
  return available.some((v) => v.toLowerCase() === stored.toLowerCase()) ? stored : ALL;
}

// ---------------------------------------------------------------------------
// Contacts
// ---------------------------------------------------------------------------

export type ContactSort = 'online' | 'firstname' | 'lastname' | 'extension';

export const CONTACT_SORTS: Array<{ value: ContactSort; label: string }> = [
  { value: 'online', label: 'Online' },
  { value: 'firstname', label: 'First Name' },
  { value: 'lastname', label: 'Last Name' },
  { value: 'extension', label: 'Extension' },
];

export function isContactOnline(c: Contact): boolean {
  const dispatch = (c.agent?.['callqueue-agent-availability-for-dispatch'] ?? '').toLowerCase();
  return dispatch === 'available' || c.presence === 'open' || c.presence === 'active';
}

export function filterContacts(contacts: Contact[], query: string, site: string, dept: string): Contact[] {
  const q = query.trim().toLowerCase();
  return contacts.filter((c) => {
    if (!matchesFilter(c.site, site) || !matchesFilter(c.department, dept)) return false;
    if (!q) return true;
    return (
      c.firstName.toLowerCase().includes(q) ||
      c.lastName.toLowerCase().includes(q) ||
      c.user.toLowerCase().includes(q) ||
      c.department.toLowerCase().includes(q)
    );
  });
}

export function sortContacts(contacts: Contact[], sort: ContactSort): Contact[] {
  const list = [...contacts];
  const byFirst = (a: Contact, b: Contact) => a.firstName.localeCompare(b.firstName);
  switch (sort) {
    case 'firstname':
      return list.sort(byFirst);
    case 'lastname':
      return list.sort((a, b) => a.lastName.localeCompare(b.lastName));
    case 'extension':
      return list.sort((a, b) => a.user.localeCompare(b.user, undefined, { numeric: true }));
    case 'online':
    default:
      return list.sort((a, b) => {
        const ao = isContactOnline(a) ? 0 : 1;
        const bo = isContactOnline(b) ? 0 : 1;
        if (ao !== bo) return ao - bo;
        const ac = a.isOnCall ? 0 : 1;
        const bc = b.isOnCall ? 0 : 1;
        if (ac !== bc) return ac - bc;
        return byFirst(a, b);
      });
  }
}

export interface Band<T> {
  site: string;
  departments: Array<{ department: string; items: T[] }>;
  count: number;
}

/** Site bands ("Default" last) with department sub-bands ("General" last). */
export function groupBySiteAndDept<T>(
  items: T[],
  siteOf: (t: T) => string,
  deptOf: (t: T) => string,
): Band<T>[] {
  const sites = new Map<string, Map<string, T[]>>();
  for (const it of items) {
    const site = normFilterValue(siteOf(it)) || 'Default';
    const dept = normFilterValue(deptOf(it)) || 'General';
    const depts = sites.get(site) ?? new Map<string, T[]>();
    const list = depts.get(dept) ?? [];
    list.push(it);
    depts.set(dept, list);
    sites.set(site, depts);
  }
  const lastly = (special: string) => (a: string, b: string) => {
    if (a === special && b !== special) return 1;
    if (b === special && a !== special) return -1;
    return a.localeCompare(b);
  };
  return Array.from(sites.keys())
    .sort(lastly('Default'))
    .map((site) => {
      const depts = sites.get(site)!;
      const departments = Array.from(depts.keys())
        .sort(lastly('General'))
        .map((department) => ({ department, items: depts.get(department)! }));
      return { site, departments, count: departments.reduce((n, d) => n + d.items.length, 0) };
    });
}

// ---------------------------------------------------------------------------
// Queues
// ---------------------------------------------------------------------------

export type QueueSort = 'name' | 'extension' | 'agents';

export const QUEUE_SORTS: Array<{ value: QueueSort; label: string }> = [
  { value: 'name', label: 'Name' },
  { value: 'extension', label: 'Extension' },
  { value: 'agents', label: 'Agents Available' },
];

export function filterQueues(queues: QueueView[], query: string, site: string, dept: string): QueueView[] {
  const q = query.trim().toLowerCase();
  return queues.filter((x) => {
    if (!matchesFilter(x.site, site) || !matchesFilter(x.department, dept)) return false;
    if (!q) return true;
    return x.ext.toLowerCase().includes(q) || x.description.toLowerCase().includes(q);
  });
}

export function sortQueues(queues: QueueView[], sort: QueueSort): QueueView[] {
  const list = [...queues];
  switch (sort) {
    case 'extension':
      return list.sort((a, b) => a.ext.localeCompare(b.ext, undefined, { numeric: true }));
    case 'agents':
      return list.sort((a, b) => b.agentsAvailable - a.agentsAvailable);
    case 'name':
    default:
      return list.sort((a, b) => a.name.localeCompare(b.name));
  }
}

// ---------------------------------------------------------------------------
// Parks
// ---------------------------------------------------------------------------

export type ParkTopology = 'domain' | 'per-site';

export function detectParkTopology(parks: ParkSlot[]): ParkTopology {
  const sites = new Set(parks.map((p) => filterKey(p.site)).filter(Boolean));
  return sites.size >= 2 ? 'per-site' : 'domain';
}

/** Parks with no site (shared overflow) plus the ones at the selected site. */
export function visibleParks(
  parks: ParkSlot[],
  topology: ParkTopology,
  scope: 'site' | 'all',
  siteFilter: string,
): ParkSlot[] {
  if (topology !== 'per-site' || scope !== 'site' || !siteFilter || siteFilter === ALL) return parks;
  return parks.filter((p) => !normFilterValue(p.site) || matchesFilter(p.site, siteFilter));
}
