/**
 * Small shared pieces built from the host kit: tone colours, dots, pills,
 * timers, section headings, empty states, and the disabled-with-a-reason
 * button used for every control Horizon apps cannot perform yet.
 */
import type * as React from 'react';

import { useNow } from '../data/clock';
import { useActions } from '../data/actions';
import { formatTimer, secondsSince } from '../model/format';
import { useKit } from './kit';

export type Tone = 'success' | 'warning' | 'error' | 'info' | 'neutral' | 'primary';

/** MUI palette path for a tone. */
export function toneColor(tone: Tone): string {
  switch (tone) {
    case 'success':
      return 'success.main';
    case 'warning':
      return 'warning.main';
    case 'error':
      return 'error.main';
    case 'info':
      return 'info.main';
    case 'primary':
      return 'primary.main';
    default:
      return 'text.disabled';
  }
}

/** Strong text colour for a tone (readable on the page background). */
export function toneText(tone: Tone): string {
  switch (tone) {
    case 'success':
      return 'success.dark';
    case 'warning':
      return 'warning.dark';
    case 'error':
      return 'error.main';
    case 'info':
      return 'info.dark';
    case 'primary':
      return 'primary.main';
    default:
      return 'text.secondary';
  }
}

type ThemeLike = { palette?: Record<string, { main?: string } | string | undefined> & { mode?: string } };

function toRgb(color: string): [number, number, number] | null {
  const c = color.trim();
  let m = /^#([0-9a-f]{3})$/i.exec(c);
  if (m) {
    const [r, g, b] = m[1].split('').map((x) => parseInt(x + x, 16));
    return [r, g, b];
  }
  m = /^#([0-9a-f]{6})/i.exec(c);
  if (m) return [0, 2, 4].map((i) => parseInt(m![1].slice(i, i + 2), 16)) as [number, number, number];
  m = /^rgba?\(\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)/i.exec(c);
  if (m) return [Number(m[1]), Number(m[2]), Number(m[3])];
  return null;
}

/**
 * A translucent tint of a tone, resolved against the host theme at render
 * (an sx function value), e.g. `bgcolor: tint('warning', 0.1)`.
 */
export function tint(tone: Tone, alpha: number) {
  return (theme: ThemeLike): string => {
    const key = tone === 'neutral' ? 'grey' : tone;
    const entry = theme?.palette?.[key];
    const main = typeof entry === 'object' && entry ? entry.main ?? (entry as Record<string, string>)[500] : undefined;
    const rgb = typeof main === 'string' ? toRgb(main) : null;
    if (!rgb) return 'transparent';
    return `rgba(${rgb[0]}, ${rgb[1]}, ${rgb[2]}, ${alpha})`;
  };
}

export function Dot({ tone, size = 10, pulse, title }: { tone: Tone; size?: number; pulse?: boolean; title?: string }) {
  const { Box, Tooltip } = useKit();
  const dot = (
    <Box
      component="span"
      role={title ? 'img' : undefined}
      aria-label={title}
      sx={{
        display: 'inline-block',
        flexShrink: 0,
        width: size,
        height: size,
        borderRadius: '50%',
        bgcolor: toneColor(tone),
        ...(pulse
          ? {
              animation: 'tvsbPulse 1.4s ease-in-out infinite',
              '@keyframes tvsbPulse': { '0%, 100%': { opacity: 1 }, '50%': { opacity: 0.35 } },
            }
          : {}),
      }}
    />
  );
  return title ? (
    <Tooltip title={title} arrow>
      {dot}
    </Tooltip>
  ) : (
    dot
  );
}

const CHIP_COLOR: Record<Tone, string> = {
  success: 'success',
  warning: 'warning',
  error: 'error',
  info: 'info',
  primary: 'primary',
  neutral: 'default',
};

export function Pill({
  tone = 'neutral',
  label,
  title,
  outlined,
  icon,
  onClick,
}: {
  tone?: Tone;
  label: React.ReactNode;
  title?: string;
  outlined?: boolean;
  icon?: string;
  onClick?: () => void;
}) {
  const { Chip, Tooltip, Icon } = useKit();
  const chip = (
    <Chip
      size="small"
      color={CHIP_COLOR[tone]}
      variant={outlined ? 'outlined' : 'filled'}
      label={label}
      icon={icon ? <Icon name={icon} size={14} /> : undefined}
      onClick={onClick}
      sx={{ fontWeight: 600, maxWidth: '100%' }}
    />
  );
  return title ? (
    <Tooltip title={title} arrow>
      <span>{chip}</span>
    </Tooltip>
  ) : (
    chip
  );
}

/** A ticking duration from `since` (epoch ms). Hidden when there is no start. */
export function Timer({
  since,
  format = formatTimer,
  color,
  bold,
  title,
}: {
  since: number | null | undefined;
  format?: (seconds: number) => string;
  color?: string;
  bold?: boolean;
  title?: string;
}) {
  const now = useNow();
  const { Typography } = useKit();
  if (since == null) return null;
  return (
    <Typography
      component="span"
      variant="caption"
      title={title}
      sx={{ fontVariantNumeric: 'tabular-nums', fontWeight: bold ? 700 : 500, color: color ?? 'text.secondary', whiteSpace: 'nowrap' }}
    >
      {format(secondsSince(since, now))}
    </Typography>
  );
}

export function SectionTitle({
  icon,
  title,
  count,
  countTone = 'info',
  caption,
  right,
}: {
  icon?: string;
  title: string;
  count?: number;
  countTone?: Tone;
  caption?: string;
  right?: React.ReactNode;
}) {
  const { Stack, Typography, Icon, Box } = useKit();
  return (
    <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1.25, minHeight: 28 }}>
      {icon ? (
        <Box sx={{ color: 'primary.main', display: 'flex' }}>
          <Icon name={icon} size={18} />
        </Box>
      ) : null}
      <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
        {title}
      </Typography>
      {count != null && count > 0 ? <Pill tone={countTone} label={count} /> : null}
      {caption ? (
        <Typography variant="caption" color="text.secondary">
          {caption}
        </Typography>
      ) : null}
      <Box sx={{ flex: 1 }} />
      {right}
    </Stack>
  );
}

export function Empty({ children, action }: { children: React.ReactNode; action?: React.ReactNode }) {
  const { Box, Typography } = useKit();
  return (
    <Box
      sx={{
        py: 2.5,
        px: 2,
        textAlign: 'center',
        borderRadius: 1.5,
        bgcolor: 'action.hover',
      }}
    >
      <Typography variant="body2" color="text.secondary">
        {children}
      </Typography>
      {action ? <Box sx={{ mt: 1 }}>{action}</Box> : null}
    </Box>
  );
}

/** Small icon + label button (outlined unless `variant` says otherwise). */
export function SmallButton({
  icon,
  label,
  onClick,
  disabled,
  busy,
  color = 'primary',
  variant = 'outlined',
  title,
  fullWidth,
}: {
  icon?: string;
  label: React.ReactNode;
  onClick?: () => void;
  disabled?: boolean;
  busy?: boolean;
  color?: 'primary' | 'secondary' | 'error' | 'info' | 'success' | 'warning' | 'inherit';
  variant?: 'text' | 'outlined' | 'contained';
  title?: string;
  fullWidth?: boolean;
}) {
  const { Button, Tooltip, Icon } = useKit();
  const btn = (
    <Button
      size="small"
      variant={variant}
      color={color}
      disabled={disabled || busy}
      onClick={onClick}
      fullWidth={fullWidth}
      startIcon={icon ? <Icon name={busy ? 'svg-spinners:ring-resize' : icon} size={16} /> : undefined}
      sx={{ textTransform: 'none', fontWeight: 600, whiteSpace: 'nowrap', minWidth: 0 }}
    >
      {label}
    </Button>
  );
  return title ? (
    <Tooltip title={title} arrow>
      <span style={fullWidth ? { display: 'block' } : undefined}>{btn}</span>
    </Tooltip>
  ) : (
    btn
  );
}

/** A control Horizon apps cannot perform yet: visible, disabled, and says why. */
export function BlockedButton({ icon, label, reason }: { icon: string; label: string; reason: string }) {
  return <SmallButton icon={icon} label={label} disabled title={reason} variant="outlined" color="inherit" />;
}

/** Icon-only action with a tooltip, busy state, and a colour. */
export function ActionIcon({
  icon,
  label,
  onClick,
  disabled,
  busy,
  color = 'default',
}: {
  icon: string;
  label: string;
  onClick?: () => void;
  disabled?: boolean;
  busy?: boolean;
  color?: 'default' | 'primary' | 'error' | 'info' | 'success' | 'warning';
}) {
  const { IconButton, Tooltip } = useKit();
  return (
    <Tooltip title={label} arrow>
      <span>
        <IconButton
          icon={busy ? 'svg-spinners:ring-resize' : icon}
          aria-label={label}
          size="small"
          color={color}
          disabled={disabled || busy}
          onClick={onClick}
        />
      </span>
    </Tooltip>
  );
}

/** The toast stack for action outcomes (bottom-right, above the page). */
export function ActionToasts() {
  const { results, dismiss } = useActions();
  const { Box, Alert } = useKit();
  if (!results.length) return null;
  return (
    <Box
      aria-live="polite"
      sx={{
        position: 'fixed',
        right: 16,
        bottom: 16,
        zIndex: 1500,
        display: 'flex',
        flexDirection: 'column',
        gap: 1,
        width: 380,
        maxWidth: 'calc(100vw - 32px)',
      }}
    >
      {results.map((r) => (
        <Alert
          key={r.id}
          severity={r.status === 'error' ? 'error' : r.status === 'ok' ? 'success' : 'info'}
          onClose={() => dismiss(r.id)}
        >
          {r.text}
        </Alert>
      ))}
    </Box>
  );
}

/** Label/value line for panels. */
export function Field({ label, children }: { label: string; children: React.ReactNode }) {
  const { Stack, Typography } = useKit();
  return (
    <Stack direction="row" spacing={1} alignItems="baseline">
      <Typography variant="caption" color="text.secondary" sx={{ minWidth: 110 }}>
        {label}
      </Typography>
      <Typography variant="body2" component="div" sx={{ minWidth: 0 }}>
        {children}
      </Typography>
    </Stack>
  );
}
