/**
 * Turning proxy / switch errors into sentences an operator can act on
 * (nsErrors.ts in the Engage switchboard). Raw vendor hostnames and stack text
 * never reach the screen.
 */
import { BudgetExceeded, isRateLimitError } from '../api/budget';

export type ErrorKind = 'scope' | 'auth' | 'not-found' | 'rate' | 'unreachable' | 'timeout' | 'refused' | 'unknown';

interface ErrLike {
  code?: unknown;
  statusCode?: unknown;
  status?: unknown;
  message?: unknown;
}

function statusOf(o: ErrLike): number | null {
  const s = typeof o.statusCode === 'number' ? o.statusCode : typeof o.status === 'number' ? o.status : null;
  if (s != null) return s;
  const m = typeof o.message === 'string' ? /\b([1-5]\d\d)\b/.exec(o.message) : null;
  return m ? Number(m[1]) : null;
}

export function classifyError(err: unknown): ErrorKind {
  if (err instanceof BudgetExceeded) return 'rate';
  if (isRateLimitError(err)) return 'rate';
  if (!err || typeof err !== 'object') return 'unknown';
  const o = err as ErrLike;
  const msg = typeof o.message === 'string' ? o.message : '';
  const status = statusOf(o);
  if (o.code === 'PERMISSION_DENIED' || status === 403 || /APP001|invalid\s+scope|forbidden/i.test(msg)) return 'scope';
  if (status === 401) return 'auth';
  if (status === 404 || /not found|no route found/i.test(msg)) return 'not-found';
  if (o.code === 'NETWORK_ERROR' || /network|failed to fetch|unreachable/i.test(msg)) return 'unreachable';
  if (status === 408 || status === 504 || /timed? ?out/i.test(msg)) return 'timeout';
  if (status != null && status >= 400) return 'refused';
  return 'unknown';
}

function cleanMessage(msg: string): string {
  return msg
    .replace(/https?:\/\/\S+/g, 'the phone system')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 240);
}

/** The reason half of "Could not X. <reason>". */
export function describeError(err: unknown): string {
  const kind = classifyError(err);
  const raw = err instanceof Error ? err.message : typeof err === 'string' ? err : '';
  switch (kind) {
    case 'scope':
      return 'Your NetSapiens account is not permitted to do that.';
    case 'auth':
      return 'Your session is no longer valid. Sign out and back in.';
    case 'not-found':
      return 'The phone system no longer has that call or record. It may have just ended.';
    case 'rate':
      return err instanceof BudgetExceeded ? err.message : 'Horizon is limiting requests for a few seconds. Try again shortly.';
    case 'unreachable':
      return 'The phone system could not be reached, so the request was not sent.';
    case 'timeout':
      return 'The phone system did not answer in time, so it is not clear whether it was applied.';
    case 'refused':
      return raw ? `The phone system refused it: ${cleanMessage(raw)}` : 'The phone system refused it.';
    default:
      return raw ? cleanMessage(raw) : 'Something went wrong.';
  }
}

/** For failed background reads shown inline. */
export function describeReadError(label: string, err: unknown): string {
  if (classifyError(err) === 'scope') {
    return `Your NetSapiens account is not permitted to read ${label}. Ask an administrator to raise your user scope.`;
  }
  return `Could not load ${label}: ${describeError(err)}`;
}
