/**
 * One of the operator's own calls (the "My Calls" rail).
 *
 * States and copy follow the Engage CallCards: Ringing / Dialing / Connected /
 * On Hold, peer name and number, a running timer, and the CRM link for
 * inbound calls. Controls are the ones the Horizon proxy allows:
 *   hang up, park (next slot or a chosen slot), decline a ringing call,
 *   mute, record, keypad (DTMF)
 * and the ones it does not (answer, hold/resume, transfer) render disabled
 * with the reason, so the card never pretends.
 */
import type * as React from 'react';
import { useState } from 'react';

import type { Line } from '../../types';
import { useSwitchboard } from '../../data/SwitchboardData';
import { useActions } from '../../data/actions';
import * as ns from '../../api/ns';
import { BLOCKED } from '../../api/ns';
import { formatPhone } from '../../model/format';
import { useKit } from '../../ui/kit';
import { ActionIcon, BlockedButton, Pill, SmallButton, Timer, tint } from '../../ui/bits';
import type { Tone } from '../../ui/bits';

const STATE: Record<Line['status'], { label: string; tone: Tone }> = {
  ringing: { label: 'Ringing', tone: 'info' },
  dialing: { label: 'Dialing', tone: 'info' },
  active: { label: 'Connected', tone: 'success' },
  held: { label: 'On Hold', tone: 'warning' },
  unknown: { label: 'Active', tone: 'info' },
};

function crmUrl(template: string, vars: Record<string, string>): string {
  let url = template;
  for (const [k, v] of Object.entries(vars)) url = url.split(`{${k}}`).join(encodeURIComponent(v));
  return /^https?:\/\//i.test(url) ? url : '';
}

export function ActiveCallCard({ line, dynamicPark }: { line: Line; dynamicPark: boolean }) {
  const { Paper, Stack, Typography, Box, Icon, TextField } = useKit();
  const sb = useSwitchboard();
  const { run, isPending } = useActions();
  const { domain, operator, parks, config, api } = sb;
  const [picker, setPicker] = useState(false);
  const [keypad, setKeypad] = useState(false);
  const [digits, setDigits] = useState('');
  const [muted, setMuted] = useState(false);
  const [recording, setRecording] = useState(false);

  const ids = line.call.controlIds;
  const key = line.call.key;
  const ringing = line.status === 'ringing' || line.status === 'dialing';
  const connected = line.status === 'active' || line.status === 'held';
  const st = STATE[line.status];
  const number = formatPhone(line.peerNumber);
  const name = line.peerName && line.peerName !== line.peerNumber ? line.peerName : number || line.peerNumber || 'Unknown';
  const inbound = line.direction === 'inbound';
  const link =
    inbound && config.crmLinkTemplate
      ? crmUrl(config.crmLinkTemplate, {
          FromCallerID: line.peerNumber,
          FromCallerName: line.call.origName,
          DNIS: line.call.dialed || operator.ext,
          Extension: operator.ext,
        })
      : '';

  const after = () => sb.refresh(['calls', 'queues', 'queued']);

  const hangUp = () =>
    run(`hangup:${key}`, () => ns.hangUp(api, domain, operator.ext, ids), {
      success: 'Call disconnected',
      failure: 'Unable to disconnect the call.',
    }).then(after);

  const decline = () =>
    run(`decline:${key}`, () => ns.decline(api, domain, operator.ext, ids), {
      success: 'Call declined',
      failure: 'Unable to decline the call.',
    }).then(after);

  const parkIn = (slot?: string) => {
    setPicker(false);
    return run(
      `park:${key}`,
      async () => {
        const got = await ns.park(api, domain, operator.ext, ids, slot);
        return got;
      },
      { success: slot ? `Call parked in slot ${slot}` : 'Call parked', failure: 'Unable to park the call.' },
    ).then(after);
  };

  const onPark = () => {
    if (dynamicPark) {
      // The Engage console parks into the first free visible slot; the v1 constrained
      // park is not available to apps, so choose the free slot here and name it.
      const free = parks.find((p) => p.calls.length === 0 && p.reportedCount === 0);
      void parkIn(free?.ext);
    } else setPicker((v) => !v);
  };

  const toggleMute = () =>
    run(`mute:${key}`, () => ns.setMuted(api, domain, operator.ext, ids, !muted), {
      success: muted ? 'Call unmuted' : 'Call muted',
      failure: muted ? 'Unable to unmute the call.' : 'Unable to mute the call.',
    }).then((ok) => ok && setMuted(!muted));

  const toggleRecord = () =>
    run(`rec:${key}`, () => ns.setRecording(api, domain, operator.ext, ids, !recording), {
      success: recording ? 'Recording stopped' : 'Recording started',
      failure: recording ? 'Unable to stop recording.' : 'Unable to start recording.',
    }).then((ok) => ok && setRecording(!recording));

  const sendDigits = (d: string) => {
    if (!d) return;
    void run(`dtmf:${key}`, () => ns.sendDtmf(api, domain, operator.ext, ids, d), {
      failure: 'Unable to send those digits.',
    }).then((ok) => ok && setDigits(''));
  };

  return (
    <Paper
      variant="outlined"
      sx={{ p: 1.5, borderWidth: 2, borderColor: tint('info', 0.5), bgcolor: 'background.paper' }}
    >
      <Stack direction="row" spacing={1} alignItems="center">
        <Box sx={{ color: inbound ? 'success.main' : 'info.main', display: 'flex' }}>
          <Icon name={inbound ? 'lucide:phone-incoming' : 'lucide:phone-outgoing'} size={18} />
        </Box>
        <Typography variant="body2" sx={{ fontWeight: 700, flex: 1, minWidth: 0 }} noWrap title={name}>
          {name}
        </Typography>
        {link ? (
          <Typography
            component="a"
            href={link}
            target="_blank"
            rel="noopener noreferrer"
            variant="caption"
            title="Open caller in CRM"
            sx={{ color: 'primary.main', fontWeight: 600 }}
          >
            CRM Link
          </Typography>
        ) : null}
      </Stack>
      <Stack direction="row" spacing={1} alignItems="center" sx={{ mt: 0.5 }}>
        {number && number !== name ? (
          <Typography variant="caption" color="text.secondary" sx={{ fontVariantNumeric: 'tabular-nums' }}>
            {number}
          </Typography>
        ) : null}
        <Pill tone={st.tone} label={st.label} />
        <Box sx={{ flex: 1 }} />
        <Timer since={line.answeredAt ?? line.startedAt} title="Call duration" />
      </Stack>

      {ringing ? (
        <Stack direction="row" spacing={1} sx={{ mt: 1.25 }} flexWrap="wrap" useFlexGap>
          <BlockedButton icon="lucide:phone" label="Answer" reason={BLOCKED.answer} />
          <SmallButton
            icon="lucide:phone-missed"
            label="Decline"
            color="inherit"
            title="Decline, and let the call carry on to the next step"
            busy={isPending(`decline:${key}`)}
            onClick={() => void decline()}
          />
          {line.direction === 'outbound' ? (
            <SmallButton
              icon="lucide:phone-off"
              label="Hang up"
              color="error"
              busy={isPending(`hangup:${key}`)}
              onClick={() => void hangUp()}
            />
          ) : null}
        </Stack>
      ) : null}

      {connected ? (
        <>
          <Stack direction="row" spacing={0.5} sx={{ mt: 1.25 }} alignItems="center" flexWrap="wrap" useFlexGap>
            {line.status === 'held' ? (
              <BlockedButton icon="lucide:play" label="Resume" reason={BLOCKED.hold} />
            ) : (
              <BlockedButton icon="lucide:pause" label="Hold" reason={BLOCKED.hold} />
            )}
            <BlockedButton icon="lucide:phone-forwarded" label="Transfer" reason={BLOCKED.transfer} />
            <SmallButton
              icon="lucide:circle-parking"
              label="Park"
              title={dynamicPark ? 'Park call to next available slot' : 'Pick a park slot'}
              busy={isPending(`park:${key}`)}
              onClick={onPark}
            />
            <Box sx={{ flex: 1 }} />
            <SmallButton
              icon="lucide:phone-off"
              label="Hang up"
              color="error"
              variant="contained"
              busy={isPending(`hangup:${key}`)}
              onClick={() => void hangUp()}
            />
          </Stack>
          <Stack direction="row" spacing={0.25} sx={{ mt: 0.5 }} alignItems="center">
            <ActionIcon
              icon={muted ? 'lucide:mic-off' : 'lucide:mic'}
              label={muted ? 'Unmute' : 'Mute'}
              color={muted ? 'warning' : 'default'}
              busy={isPending(`mute:${key}`)}
              onClick={() => void toggleMute()}
            />
            <ActionIcon
              icon={recording ? 'lucide:circle-stop' : 'lucide:disc'}
              label={recording ? 'Stop recording' : 'Record'}
              color={recording ? 'error' : 'default'}
              busy={isPending(`rec:${key}`)}
              onClick={() => void toggleRecord()}
            />
            <ActionIcon
              icon="lucide:grid-3x3"
              label={keypad ? 'Hide keypad' : 'Keypad (send digits)'}
              color={keypad ? 'primary' : 'default'}
              onClick={() => setKeypad((v) => !v)}
            />
          </Stack>

          {picker ? (
            <Paper variant="outlined" sx={{ mt: 1, p: 1 }}>
              <Typography variant="caption" sx={{ fontWeight: 700, display: 'block', mb: 0.5 }}>
                Park to slot
              </Typography>
              {parks.length === 0 ? (
                <Stack spacing={0.75}>
                  <Typography variant="caption" color="text.secondary">
                    No park slots
                  </Typography>
                  <SmallButton icon="lucide:circle-parking" label="Let the phone system pick" onClick={() => void parkIn()} />
                </Stack>
              ) : (
                <Stack spacing={0.5}>
                  {parks.map((p) => {
                    const taken = p.calls.length > 0 || p.reportedCount > 0;
                    return (
                      <SmallButton
                        key={p.ext}
                        fullWidth
                        variant="text"
                        color="inherit"
                        disabled={taken}
                        title={taken ? 'Slot already occupied' : `Park to ${p.ext}`}
                        label={p.name && p.name !== p.ext ? `${p.ext} · ${p.name}` : p.ext}
                        onClick={() => void parkIn(p.ext)}
                      />
                    );
                  })}
                </Stack>
              )}
            </Paper>
          ) : null}

          {keypad ? (
            <Stack direction="row" spacing={1} sx={{ mt: 1 }} alignItems="center">
              <TextField
                size="small"
                placeholder="Digits to send"
                value={digits}
                onChange={(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
                  setDigits(e.target.value.replace(/[^0-9*#]/g, ''))
                }
                onKeyDown={(e: React.KeyboardEvent) => {
                  if (e.key === 'Enter') sendDigits(digits);
                }}
                inputProps={{ 'aria-label': 'Digits to send into the call', inputMode: 'tel' }}
                sx={{ flex: 1 }}
              />
              <SmallButton label="Send" busy={isPending(`dtmf:${key}`)} disabled={!digits} onClick={() => sendDigits(digits)} />
            </Stack>
          ) : null}
        </>
      ) : null}
    </Paper>
  );
}
