/**
 * What each NetSapiens user scope may do in the console. Same tiers as the
 * Engage switchboard (capabilities.ts there), and it fails closed: an unknown
 * or empty scope gets the basic tier.
 */

export interface Capabilities {
  tier: 'supervisor' | 'agent' | 'basic';
  /** Operate mode (queue list, waiting callers, agent roster). */
  operationsConsole: boolean;
  /** Analyze mode. */
  analytics: boolean;
  /** Wallboard mode. */
  wallboard: boolean;
  agentRoster: boolean;
  /** Add/remove queue members and flip other agents' availability. */
  manageQueueAgents: boolean;
  /** Voicemail boxes of other users. */
  voicemailManagement: boolean;
  /** Read the whole domain's calls (otherwise the operator's own only). */
  domainCalls: boolean;
  /** Other users' answer rules and call history. */
  manageUsers: boolean;
}

const SUPERVISOR_SCOPES = new Set([
  'super user',
  'site manager',
  'office manager',
  'reseller',
  'call center supervisor',
]);

const AGENT_SCOPES = new Set(['call center agent']);

export function capabilitiesFor(scope: string | undefined): Capabilities {
  const s = (scope ?? '').trim().toLowerCase();
  if (SUPERVISOR_SCOPES.has(s)) {
    return {
      tier: 'supervisor',
      operationsConsole: true,
      analytics: true,
      wallboard: true,
      agentRoster: true,
      manageQueueAgents: true,
      voicemailManagement: true,
      domainCalls: true,
      manageUsers: true,
    };
  }
  if (AGENT_SCOPES.has(s)) {
    return {
      tier: 'agent',
      operationsConsole: false,
      analytics: false,
      wallboard: false,
      agentRoster: false,
      manageQueueAgents: false,
      voicemailManagement: false,
      domainCalls: false,
      manageUsers: false,
    };
  }
  return {
    tier: 'basic',
    operationsConsole: false,
    analytics: false,
    wallboard: false,
    agentRoster: false,
    manageQueueAgents: false,
    voicemailManagement: false,
    domainCalls: false,
    manageUsers: false,
  };
}

/** Scopes that work across domains and get a domain picker. */
export function canPickDomain(scope: string | undefined): boolean {
  const s = (scope ?? '').trim().toLowerCase();
  return s === 'super user' || s === 'reseller' || s === 'site manager';
}
