/**
 * Live-signal bridge.
 *
 * A Horizon app cannot subscribe to the domain call / agent / queue / contacts
 * feeds the Engage switchboard uses (those live on the :8001 socket, and the
 * app has no credential for it). What an app CAN receive is the host-relayed
 * streams, each gated by a `<stream>:listen` capability:
 *
 *   call-events   the signed-in user's own call lifecycle
 *   device        device state changes
 *   registration  SIP registration changes
 *   subscriber    user/subscriber record changes
 *
 * None of these is the domain-wide board feed, but each is a hint that
 * something changed, so every relayed event is re-emitted as one signal on the
 * app's event bus and the data provider pulls its next poll forward.
 *
 * IMPORTANT: each stream id is written as a literal at its own call site. The
 * platform analyser grants `<stream>:listen` by reading string literals out of
 * the bundle; v0.2.0 subscribed in a loop over an array, the analyser saw no
 * literal, and the host denied device/registration/subscriber with
 * "lacks device:listen".
 */
import type { RemoteAppSDK, StreamEvent } from '@netsapiens/horizon-sdk';

/** The event-bus key the data provider listens on. */
export const LIVE_SIGNAL_EVENT = 'switchboard:live-signal';

export interface LiveSignal {
  stream: 'call-events' | 'device' | 'registration' | 'subscriber';
  type?: string;
  at: number;
}

type EventBus = { emit: (event: string, data?: unknown) => void };

export function installLiveSignals(sdk: RemoteAppSDK, eventBus: EventBus): () => void {
  const cleanups: Array<() => void> = [];
  const emit = (stream: LiveSignal['stream'], type?: string) => {
    eventBus.emit(LIVE_SIGNAL_EVENT, { stream, type, at: Date.now() } satisfies LiveSignal);
  };
  const attempt = (name: string, subscribe: () => () => void) => {
    try {
      cleanups.push(subscribe());
    } catch (e) {
      console.warn(`[switchboard] ${name} stream unavailable:`, e);
    }
  };

  attempt('call-events', () =>
    sdk.subscribeToCallEvents(['call-started', 'call-answered', 'call-missed', 'call-ended'], (event) =>
      emit('call-events', event.type),
    ),
  );
  attempt('device', () => sdk.subscribeToStream('device', [], (event: StreamEvent) => emit('device', event.type)));
  attempt('registration', () =>
    sdk.subscribeToStream('registration', [], (event: StreamEvent) => emit('registration', event.type)),
  );
  attempt('subscriber', () =>
    sdk.subscribeToStream('subscriber', [], (event: StreamEvent) => emit('subscriber', event.type)),
  );

  return () => {
    for (const off of cleanups) {
      try {
        off();
      } catch {
        /* best effort */
      }
    }
  };
}
